async fn sealed_publication(
    temporary: &TempDir,
    load: &DeclarationLoad,
    expected_revision: i64,
    content_changed: bool,
) -> anyhow::Result<crate::domain::models::declaration_sync::PreparedPublication> {
    use crate::domain::{
        models::declaration_sync::{CompleteDeclarationSnapshot, DeclarationSyncMode, DiscoveryWindow, OwnedDeclaration},
        repositories::declaration_sync::DeclarationSyncStorage,
        services::declaration_sync::{sha256_digest, source_content_digest},
    };
    let partition = super::super::declaration_cleaning::read_partition(
        &temporary.path().join("data").join(load.ingestion_key.to_string()).join("raw/declarations/4613.parquet"),
    )?;
    let scope = vec![partition.member];
    let declarations = partition.declarations.into_iter().map(|evidence| {
        let declaration = evidence.declaration().clone();
        (declaration.id(), OwnedDeclaration { member: partition.member, declaration })
    }).collect();
    let date = chrono::NaiveDate::from_ymd_opt(2026, 10, 12).unwrap();
    let snapshot = CompleteDeclarationSnapshot {
        schema_version: 1,
        run: if content_changed { load.ingestion_key.uuid() } else { Uuid::now_v7() },
        expected_revision, mode: DeclarationSyncMode::Reconcile, source: "test evidence".into(),
        window: DiscoveryWindow { from: date, through: date },
        scope_sha256: sha256_digest(&serde_json::to_vec(&scope)?), scope,
        pending_members: vec![], exclusions: Default::default(), omissions: vec![], receipts: vec![],
        artifacts: Default::default(), content_sha256: source_content_digest(&declarations)?,
        declarations, content_changed, captured_at: Utc::now(),
    };
    let root = tempfile::Builder::new().prefix("sealed-").tempdir_in(temporary.path())?;
    let store = super::super::declaration_sync::DeclarationSnapshotStore::new(root.path(), 100)?;
