    root.keep();
    Ok(publication)
}

#[sqlx::test(migrations = "../db/migrations")]
async fn publication_retry_no_load_and_stale_guards(pool: sqlx::PgPool) -> anyhow::Result<()> {
    let (temporary, load) = resolved_test_run().await?;
    sqlx::query!("INSERT INTO exposed.members (parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons) VALUES (4613, 'Test member', 1, 'Test party', 1, 'Test constituency', true)").execute(&pool).await?;
    let repository = ExposedDatabase::from(pool.clone());
    let initial = sealed_publication(&temporary, &load, 0, true).await?;
    assert!(repository.publish_declaration_sync(&initial, Some(&load)).await?);
    let before = database_snapshot(&pool).await?;
    assert!(!repository.publish_declaration_sync(&initial, Some(&load)).await?);
    assert!(repository.load_declarations(&load).await.unwrap_err().to_string().contains("sync owns the projection"));
    let stale = sealed_publication(&temporary, &load, 0, false).await?;
    assert!(repository.publish_declaration_sync(&stale, None).await.unwrap_err().to_string().contains("stale declaration publication base"));
    let unchanged = sealed_publication(&temporary, &load, 1, false).await?;
    assert!(repository.publish_declaration_sync(&unchanged, None).await?);
    assert!(!repository.publish_declaration_sync(&unchanged, None).await?);
    assert_eq!(database_snapshot(&pool).await?, before);
    let revision = sqlx::query_scalar!("SELECT revision FROM exposed.declaration_sync_runs r JOIN exposed.declaration_sync_head h USING (ingestion_key)").fetch_one(&pool).await?;
    assert_eq!(revision, 2);
    Ok(())
}

#[sqlx::test(migrations = "../db/migrations")]
async fn initial_publication_rejects_intervening_legacy_load(pool: sqlx::PgPool) -> anyhow::Result<()> {
    let (temporary, load) = resolved_test_run().await?;
    sqlx::query!("INSERT INTO exposed.members (parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons) VALUES (4613, 'Test member', 1, 'Test party', 1, 'Test constituency', true)").execute(&pool).await?;
    let repository = ExposedDatabase::from(pool.clone());
    let publication = sealed_publication(&temporary, &load, 0, true).await?;
    let (_legacy_files, mut legacy) = resolved_test_run().await?;
    legacy.declarations[0].source_declaration_id = DeclarationId::new(9000)?;
    for entry in &mut legacy.funding_entries {
        if entry.source_declaration_id.value() == 1 {
            entry.source_declaration_id = DeclarationId::new(9000)?;
        }
    }
    repository.load_declarations(&legacy).await?;
    let before = database_snapshot(&pool).await?;
    let error = repository.publish_declaration_sync(&publication, Some(&load)).await.unwrap_err();
    assert!(error.to_string().contains("initial publication omitted current declarations"), "{error}");
    assert_eq!(database_snapshot(&pool).await?, before);
    assert_eq!(sqlx::query_scalar!("SELECT count(*) AS \"count!\" FROM exposed.declaration_sync_head").fetch_one(&pool).await?, 0);
    Ok(())
}
